// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/miniapp/config", wrapper.GetMiniAppConfig)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/me", wrapper.GetCurrentUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/groups", wrapper.ListAttendanceGroups)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/groups/page", wrapper.ListAttendanceGroupPage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/records", wrapper.ListAttendanceRecords)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/records/{id}", wrapper.GetAttendanceRecord)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/monthly", wrapper.GetAttendanceMonthlyReport)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/monthly/summary", wrapper.GetAttendanceMonthlySummary)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/attendance/launch", wrapper.ExchangeAttendanceLaunch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/attendance/punches", wrapper.SubmitAttendancePunch)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/attendance/corrections", wrapper.ProposeAttendanceCorrection)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/corrections/{id}", wrapper.GetAttendanceCorrectionStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/attendance/corrections/{id}/review", wrapper.GetAttendanceCorrectionReview)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/attendance/corrections/{id}/approve", wrapper.ApproveAttendanceCorrection)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/session", wrapper.DeleteSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/session", wrapper.CreateSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/session/refresh", wrapper.RefreshSession)

	return m
}

